I("E-001", sw, "শিশুর খিঁচুনি", "শিশুর খিঁচুনি হলে তাকে একপাশে কাত করে শুইয়ে দিন, গায়ের আঁটসাঁট কাপড় ঢিলা করুন এবং মুখে কিছু দেবেন না বা হাত-পা চেপে ধরবেন না। খিঁচুনি কত সময় চলল তা খেয়াল রাখুন এবং থেমে গেলেও এখনই শিশুকে হাসপাতালে নিন।", "high", HW, ["Q017"])
I("E-002", sw, "সাপে কামড়ালে", "সাপে কামড়ালে রোগীকে শান্ত রেখে কামড়ানো অঙ্গ নড়াচড়া না করিয়ে স্থির রাখুন এবং আংটি-চুড়ি খুলে ফেলুন। কামড়ের জায়গা কাটা, মুখে বিষ টানা বা ওঝা-কবিরাজের কাছে সময় নষ্ট করবেন না। অবিলম্বে অ্যান্টিভেনম আছে এমন নিকটস্থ হাসপাতালে নিন।", "high", HW, ["Q026"])
