I("K-004", kr, "সবজির বীজ সংরক্ষণ", "সবজির বীজ ভালোভাবে শুকিয়ে ছায়ায় ঠান্ডা করে বায়ুরোধী কৌটা বা বোতলে ভরে ঠান্ডা, শুকনো জায়গায় রাখতে হয়। ভেতরে শুকনো ছাই বা নিমপাতা দিলে পোকা কম লাগে। বীজে আর্দ্রতা ঢুকলে অঙ্কুরোদগম ক্ষমতা কমে যায়, তাই কৌটার মুখ শক্ত করে লাগান ও লেবেল দিন।", "medium", AG, ["Q009"])
I("K-005", kr, "মাটির স্বাস্থ্য রক্ষা", "মাটির স্বাস্থ্য ভালো রাখতে জৈব সার (গোবর, কম্পোস্ট) দেওয়া, শস্য পর্যায় মেনে ডাল জাতীয় ফসল আবাদ করা এবং শুধু ইউরিয়ায় নির্ভর না করে সুষম সার ব্যবহার করা উচিত। সার দেওয়ার আগে মাটি পরীক্ষা করালে কোন পুষ্টি কম তা জানা যায়।", "high", AG, ["Q035"])
I("K-006", kr, "সবজি খেতে জলাবদ্ধতা", "সবজি খেতে পানি জমলে দ্রুত নালা কেটে পানি বের করুন এবং ভবিষ্যতের জন্য উঁচু বেড ও নিষ্কাশন নালা রাখুন। পানি নামার পর মাটি একটু শুকাতে দিয়ে গাছের গোড়ায় মাটি তুলে দিন, রোগাক্রান্ত গাছ তুলে ফেলুন এবং প্রয়োজনে কৃষি অফিসারের পরামর্শে ছত্রাকনাশক ব্যবহার করুন।", "medium", AG, ["Q083"])
I("K-007", kr, "কম্পোস্ট সার তৈরি", "গোবর, গাছের পাতা, খড় ও রান্নাঘরের বর্জ্য স্তরে স্তরে সাজিয়ে গর্তে বা স্তূপে রেখে কম্পোস্ট সার বানানো যায়। স্তূপ ভেজা রাখুন, ঢেকে দিন এবং কয়েক সপ্তাহ পরপর উল্টে দিন; দুই থেকে তিন মাসে সার তৈরি হয়। কেঁচো সার বানাতে কেঁচো ব্যবহার করা হয়।", "high", AG, ["Q111"])
I("K-008", kr, "গম বোনার সময়", "গম সাধারণত অগ্রহায়ণের প্রথম থেকে তৃতীয় সপ্তাহে (মোটামুটি পনেরো থেকে ত্রিশ নভেম্বর) বোনা ভালো। দেরিতে বুনলে ফলন কমে যায়। বীজ বোনার আগে জমি ভালো করে তৈরি করে সুস্থ বীজ ব্যবহার করুন।", "medium", AG, ["Q091"])
I("K-009", kr, "পাট পচানো", "পাট একশ থেকে একশ বিশ দিনে কেটে আঁটি বেঁধে দুই-তিন দিন পাতা ঝরিয়ে পরিষ্কার ধীর স্রোতের বা জমা পানিতে ডুবিয়ে পচাতে হয়। ডোবানোর পর আঁশ সহজে ছাড়লে (সাধারণত দশ থেকে বিশ দিনে) তুলে আঁশ ছাড়িয়ে পরিষ্কার পানিতে ধুয়ে রোদে শুকাতে হয়। বেশি পচালে আঁশের মান নষ্ট হয়।", "medium", AG, ["Q098"])
I("K-010", kr, "আলুর লেট ব্লাইট", "আলুর লেট ব্লাইটে ঠান্ডা, কুয়াশা-মেঘলা ও আর্দ্র আবহাওয়ায় পাতায় পানিভেজা কালচে দাগ হয়, পাতার নিচে সাদা ছাতা পড়ে এবং খুব দ্রুত ছড়িয়ে পুরো খেত ঝলসে যেতে পারে। সুস্থ বীজ, রোগ সহনশীল জাত ও খেত পরিষ্কার রাখা সহায়ক। ছত্রাকনাশক কৃষি অফিসারের পরামর্শে দিন।", "high", AG, ["Q041"])
I("K-011", kr, "ধানের মাজরা পোকা", "মাজরা পোকার আক্রমণে ধানের কুশি অবস্থায় ডিগ পাতা শুকিয়ে যায় (মরা ডিগ) এবং থোড় অবস্থায় শীষ সাদা হয়ে যায় (সাদা শীষ)। ডিমের গাদা সংগ্রহ করে নষ্ট করা, আলোর ফাঁদ, জমিতে ডাল পুঁতে পাখি বসার ব্যবস্থা ও পরিমিত ইউরিয়া সহায়ক। কীটনাশক লাগলে কৃষি অফিসারের পরামর্শ নিন।", "medium", AG, ["Q043"])
I("K-012", kr, "বীজতলায় হলুদ চারা", "বীজতলায় চারা হলুদ হলে কারণ হতে পারে নাইট্রোজেনের অভাব, অতিরিক্ত ঠান্ডা, পানি জমে থাকা বা জিংকের অভাব। জমে থাকা পানি বের করুন, প্রয়োজনে কৃষি অফিসারের পরামর্শে অল্প ইউরিয়া বা জিংক দিন। দাগযুক্ত বা মরচে রঙের চারা দেখলে রোগ বা পুষ্টির অভাব কি না তা দেখে নিন।", "medium", AG, ["Q046"])
