I("K-015", kr, "শীতকালীন সবজির সময়", "শীতকালীন সবজির মধ্যে ফুলকপি, বাঁধাকপি ও টমেটোর চারা সাধারণত আশ্বিন-কার্তিকে (অক্টোবর) বীজতলায় তৈরি হয় এবং কার্তিক-অগ্রহায়ণে খেতে লাগানো হয়। মুলা, পালংশাক ও লালশাক কার্তিক থেকে পৌষ পর্যন্ত বোনা যায়। জাতভেদে সময় একটু বদলাতে পারে।", "medium", AG, ["Q183"])
I("K-016", kr, "সবজিতে জৈব উপায়ে পোকা দমন", "সবজিতে পোকা দমনে হাত দিয়ে পোকা ও ডিম তোলা, আক্রান্ত ডগা কেটে ফেলা, ফেরোমন ও হলুদ আঠালো ফাঁদ ব্যবহার, খেতে পাখি বসার ডাল পোঁতা এবং নিমের নির্যাস স্প্রে করা কার্যকর। একই জমিতে বারবার একই ফসল না করে ফসল ঘুরিয়ে চাষ করুন।", "high", AG, ["Q128"])
