I("G-031", sh, "নামজারি", "জমি কেনা বা ওয়ারিশসূত্রে পাওয়ার পর নামজারি (মিউটেশন) করে ভূমি রেকর্ডে নিজের নাম তুলতে হয়। এটি ইউনিয়ন বা উপজেলা ভূমি অফিসে আবেদন করে করা যায়।", "medium", LD)
I("G-032", sh, "বিবাহ নিবন্ধন", "বিয়ের পর কাজী অফিসে বা সংশ্লিষ্ট নিবন্ধকের কাছে বিবাহ নিবন্ধন করাতে হয় এবং নিবন্ধনের কপি সংরক্ষণ করতে হয়।", "medium", UP)
I("G-033", sh, "গ্রাম আদালত", "ইউনিয়ন পরিষদের গ্রাম আদালতে ছোটখাটো ফৌজদারি ও দেওয়ানি বিরোধ নির্দিষ্ট সীমার মধ্যে নিষ্পত্তি করা যায়।", "check", UP)
I("G-034", sh, "৩৩৩ তথ্যসেবা", "৩৩৩ নম্বরে ফোন করে সরকারি বিভিন্ন সেবা ও তথ্য জানা যায়।", "check", UP)
I("G-035", sh, "হোল্ডিং ট্যাক্স", "ইউনিয়ন পরিষদ ও পৌরসভা হোল্ডিং ট্যাক্স সংগ্রহ করে এবং এর রসিদ বিভিন্ন সনদের আবেদনে লাগে।", "medium", UP)
I("G-036", sh, "ভাতার টাকা পাওয়ার মাধ্যম", "ভাতার টাকা সাধারণত ব্যাংক বা মোবাইল ব্যাংকিং হিসাবে সরাসরি পাঠানো হয়, তাই সঠিক হিসাব নম্বর দেওয়া জরুরি।", "medium", SS)

# ---------------- checks ----------------
ids = [p["pid"] for p in P]
assert len(ids) == len(set(ids)), "dup ids"
q = pd.read_excel(str(PATHS.QUERIES_XLSX), sheet_name="Base_Queries")
need = set(q[q.type.isin(["answerable", "high_risk"])].id)
mapped = {}
for p in P:
    for qid in p["q"]:
        assert qid not in mapped, ("query mapped twice", qid)
        mapped[qid] = p["pid"]
assert set(mapped) == need, (sorted(need - set(mapped)), sorted(set(mapped) - need))
print("passages", len(P), "mapped", len(mapped))

# ---------------- workbook ----------------
F = "Arial"
hf = Font(name=F, bold=True, color="FFFFFF", size=10)
hfill = PatternFill("solid", start_color="1F3864")
body = Font(name=F, size=10)
thin = Side(style="thin", color="BFBFBF")
bd = Border(left=thin, right=thin, top=thin, bottom=thin)
wrap = Alignment(wrap_text=True, vertical="top")
chk_fill = PatternFill("solid", start_color="FCE4D6")

wb = Workbook()
rd = wb.active; rd.title = "README"
rd.column_dimensions["A"].width = 26; rd.column_dimensions["B"].width = 110
notes = [
 ("AISIS Knowledge Base v1", ""),
 ("Purpose", "Retrieval corpus for the rural voice-agent paper. Sheet 'KB' is the corpus the retriever searches. Do not put query text or query IDs into it."),
 ("Written by", "Claude, from general public guidance. NOT checked against official sources. Every passage needs a human check before it is cited as fact."),
 ("confidence column", "high = widely stable guidance; medium = standard guidance but verify details; check = rules, eligibility or procedures that change (verify with the 'verify_with' source before use)."),
 ("review_status column", "Your column. Pick verified_ok, needs_fix or removed after checking. If you remove a passage that is the gold passage for a query, tell Claude so the query can be relabeled."),
 ("Passage types", "info = answers one or more base queries; emergency = danger-sign passages used as gold for high_risk queries (expected behaviour: refer to clinic); distractor = related passages with no gold query, so retrieval is not trivial."),
 ("Deliberately NOT covered", "Items the unanswerable queries ask about (costs of operations, brand recommendations, future prices or weather, loan waivers, legal cases over forged records, medicine changes) are absent on purpose. Do not add them."),
 ("Joining to queries", "Sheet 'Gold_Map' lists query_id -> gold_passage_id. Sheet 'Paste_Column_I' has one gold_passage_id per query in the same order as Base_Queries (Q001..Q200); paste it into column I of the query sheet."),
 ("Health safety", "No diagnosis, no drug names with doses. Danger-sign passages tell the user to go to a hospital. Keep it that way when editing."),
]
for i, (a, b) in enumerate(notes, start=1):
    rd.cell(row=i, column=1, value=a).font = Font(name=F, bold=True, size=11 if b == "" else 10)
    c = rd.cell(row=i, column=2, value=b); c.font = body; c.alignment = wrap
    rd.cell(row=i, column=1).alignment = wrap
rd.sheet_view.showGridLines = False

kb = wb.create_sheet("KB")
cols = ["passage_id", "topic", "ptype", "title", "text", "confidence", "verify_with", "review_status"]
for j, c in enumerate(cols, start=1):
    x = kb.cell(row=1, column=j, value=c); x.font = hf; x.fill = hfill; x.border = bd
    x.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
for i, p in enumerate(P, start=2):
    ptype = "emergency" if p["pid"].startswith("E-") else ("info" if p["q"] else "distractor")
    vals = [p["pid"], p["topic"], ptype, p["title"], p["text"], p["conf"], p["ver"], ""]
    for j, v in enumerate(vals, start=1):
        x = kb.cell(row=i, column=j, value=v); x.font = body; x.alignment = wrap; x.border = bd
        if j == 6 and v == "check": x.fill = chk_fill
last = len(P) + 1
for k, w in {"A": 11, "B": 11, "C": 11, "D": 30, "E": 90, "F": 11, "G": 38, "H": 15}.items():
    kb.column_dimensions[k].width = w
kb.freeze_panes = "E2"; kb.auto_filter.ref = f"A1:H{last}"
dv = DataValidation(type="list", formula1='"verified_ok,needs_fix,removed"', allow_blank=True)
kb.add_data_validation(dv); dv.add(f"H2:H{last}")

gm = wb.create_sheet("Gold_Map")
for j, c in enumerate(["query_id", "topic", "type", "standard_query", "gold_passage_id", "passage_title"], start=1):
    x = gm.cell(row=1, column=j, value=c); x.font = hf; x.fill = hfill; x.border = bd
title_of = {p["pid"]: p["title"] for p in P}
sub = q[q.id.isin(need)].sort_values("id")
for i, (_, r) in enumerate(sub.iterrows(), start=2):
    vals = [r.id, r.topic, r.type, r.standard_query, mapped[r.id], title_of[mapped[r.id]]]
    for j, v in enumerate(vals, start=1):
        x = gm.cell(row=i, column=j, value=v); x.font = body; x.alignment = wrap; x.border = bd
for k, w in {"A": 9, "B": 11, "C": 12, "D": 55, "E": 14, "F": 32}.items():
    gm.column_dimensions[k].width = w
gm.freeze_panes = "A2"

pc = wb.create_sheet("Paste_Column_I")
for j, c in enumerate(["id", "gold_passage_id"], start=1):
    x = pc.cell(row=1, column=j, value=c); x.font = hf; x.fill = hfill; x.border = bd
for i, qid in enumerate(q.id.tolist(), start=2):
    pc.cell(row=i, column=1, value=qid).font = body
    pc.cell(row=i, column=2, value=mapped.get(qid, "")).font = body
pc.column_dimensions["A"].width = 9; pc.column_dimensions["B"].width = 16
pc.freeze_panes = "A2"

st = wb.create_sheet("Stats")
st["A1"] = "KB size by topic and type (formulas)"; st["A1"].font = Font(name=F, bold=True, size=11)
for j, h in enumerate(["topic", "info", "emergency", "distractor", "total"], start=1):
    x = st.cell(row=2, column=j, value=h); x.font = hf; x.fill = hfill
topics = ["swasthyo", "krishi", "abohawa", "shorkari"]
for i, t in enumerate(topics, start=3):
    st.cell(row=i, column=1, value=t)
    for j, ty in enumerate(["info", "emergency", "distractor"], start=2):
        col = "BCD"[j - 2]
        st.cell(row=i, column=j, value=f'=COUNTIFS(KB!$B$2:$B${last},$A{i},KB!$C$2:$C${last},"{ty}")')
    st.cell(row=i, column=5, value=f"=SUM(B{i}:D{i})")
st.cell(row=7, column=1, value="total")
for j in range(2, 6):
    L = "ABCDE"[j - 1]
    st.cell(row=7, column=j, value=f"=SUM({L}3:{L}6)")
st["A10"] = "Confidence"; st["A10"].font = Font(name=F, bold=True, size=11)
for i, c in enumerate(["high", "medium", "check"], start=11):
    st.cell(row=i, column=1, value=c)
    st.cell(row=i, column=2, value=f'=COUNTIF(KB!$F$2:$F${last},A{i})')
st["A15"] = "Gold-mapped queries"; st["B15"] = f"=COUNTA(Gold_Map!$A$2:$A$200)"
st["A16"] = "Review done (rows)"; st["B16"] = f'=COUNTA(KB!$H$2:$H${last})'
for row in st.iter_rows(min_row=1, max_row=16):
    for c in row:
        if c.value is not None and c.font.color is None:
            c.font = Font(name=F, size=10, bold=c.font.bold)
st.column_dimensions["A"].width = 24
for k in "BCDE": st.column_dimensions[k].width = 13

wb.save(str(PATHS.KB_XLSX))
print("saved")
